function pairCards(themes, kind) {
  const out = []
  themes.forEach((theme, index) => {
    const pairs = combos(theme.items, 2).sort((a, b) => hash(`${index}:${a.join('|')}`) - hash(`${index}:${b.join('|')}`)).slice(0, 100)
    pairs.forEach(([a, b]) => {
      if (kind === 'agree') out.push(G(theme.compare.replaceAll('{a}', a).replaceAll('{b}', b)))
    })
  })
  return out
}

function guessCards(themes) {
  const out = []
  themes.forEach((theme, index) => {
    const sets = combos(theme.items, 4).sort((a, b) => hash(`g:${index}:${a.join('|')}`) - hash(`g:${index}:${b.join('|')}`)).slice(0, 100)
    sets.forEach(options => out.push(G(theme.guess, { options })))
  })
  return out
}

function rateCards(themes, mode) {
  const frames = mode === 'friend'
    ? [
      'Rate how much you personally enjoy {item} from 1 to 10.',
      'Rate how important {item} is to you from 1 to 10.',
      'Rate how much you would miss {item} if it disappeared for a year, from 1 to 10.',
      'Rate how strongly {item} fits your personality from 1 to 10.',
      'Rate how likely you are to choose {item} when you have the option, from 1 to 10.',
      'Rate how much {item} improves your mood from 1 to 10.',
      'Rate how much you would recommend {item} to someone like you, from 1 to 10.',
    ]
    : [
      'Rate how much {item} matters to you in a relationship from 1 to 10.',
      'Rate how much you enjoy {item} as part of couple life from 1 to 10.',
      'Rate how much you would miss {item} if a relationship had none of it, from 1 to 10.',
      'Rate how naturally {item} comes to you in relationships from 1 to 10.',
      'Rate how much {item} affects your attraction or connection from 1 to 10.',
      'Rate how important {item} would be in a long-term relationship from 1 to 10.',
      'Rate how much effort you would put into protecting {item} in a relationship from 1 to 10.',
    ]
  const out = []
  themes.forEach((theme, themeIndex) => theme.items.forEach((item, itemIndex) => frames.forEach((frame, frameIndex) => {
    out.push({ card: G(frame.replaceAll('{item}', item)), sort: hash(`r:${themeIndex}:${itemIndex}:${frameIndex}`) })
  })))
  return out.sort((a, b) => a.sort - b.sort).map(entry => entry.card)
}

