function redCards(groups) {
  const out = []
  groups.forEach((group, gi) => {
    const pairs = []
    group.behaviours.forEach((behaviour, bi) => group.contexts.forEach((context, ci) => pairs.push({ behaviour, context, sort: hash(`red:${gi}:${bi}:${ci}`) })))
    pairs.sort((a, b) => a.sort - b.sort).slice(0, 100).forEach(({ behaviour, context }) => out.push(G(`They ${behaviour}, ${context}.`)))
  })
  return out
}

