function pettyCards(groups) {
  const out = []
  groups.forEach((group, gi) => group.triggers.forEach((trigger, ti) => group.reactions.forEach((reaction, ri) => {
    out.push({ card: G(`Petty or valid: ${trigger}, so ${reaction}?`), sort: hash(`p:${gi}:${ti}:${ri}`) })
  })))
  return out.sort((a, b) => a.sort - b.sort).map(entry => entry.card)
}

