const lenses = ['that still makes you laugh','you would handle differently now','that taught you something unexpected','you rarely tell people about','where the ending surprised you']

function storyCards(groups) {
  const out = []
  groups.forEach((events, gi) => events.forEach((event, ei) => lenses.forEach((lens, li) => out.push({ card: G(`Tell me about ${event} ${lens}.`), sort: hash(`s:${gi}:${ei}:${li}`) }))))
  return out.sort((a, b) => a.sort - b.sort).map(entry => entry.card)
}

function withStarters(id, mode, generated) {
  return unique([...(starterPrompts[id]?.[mode] || []), ...generated], 1000)
}

function build(mode) {
  const themes = mode === 'friend' ? friendThemes : relationshipThemes
  return {
    'guess-my-answer': withStarters('guess-my-answer', mode, guessCards(themes)),
    'agree-disagree': withStarters('agree-disagree', mode, pairCards(themes, 'agree')),
    'rate-it': withStarters('rate-it', mode, rateCards(themes, mode)),
    'red-green-depends': withStarters('red-green-depends', mode, redCards(mode === 'friend' ? friendRed : relationshipRed)),
    'petty-or-valid': withStarters('petty-or-valid', mode, pettyCards(mode === 'friend' ? friendPetty : relationshipPetty)),
    'tell-the-story': withStarters('tell-the-story', mode, storyCards(mode === 'friend' ? friendStory : relationshipStory)),
  }
}

const friend = build('friend')
const relationship = build('relationship')

export const openGamePrompts1000 = Object.fromEntries(
  Object.keys(friend).map(id => [id, { friend: friend[id], relationship: relationship[id] }]),
)

export const openGameIds1000 = new Set(Object.keys(openGamePrompts1000))
